import 'dart:io';

import 'package:xterm/src/utils/unicode_v11.dart';

// The Dart Unicode tables are the source of truth for both terminal parsers.
// Regenerate after changing unicode_v11.dart; --check is used by the native gate.
void main(List<String> arguments) {
  final output = File('native/terminal_core/src/generated_width_table.rs');
  final result = StringBuffer()
    ..writeln(
      '// Generated by tool/generate_terminal_width_table.dart. Do not edit.',
    )
    ..writeln('// Source: packages/xterm/lib/src/utils/unicode_v11.dart.')
    ..writeln();

  writeRanges(
    result,
    'MODERN_ZERO',
    (codePoint) => unicodeV11.wcwidth(codePoint) == 0,
  );
  writeRanges(
    result,
    'MODERN_WIDE',
    (codePoint) => unicodeV11.wcwidth(codePoint) == 2,
  );
  writeRanges(
    result,
    'LEGACY_ZERO',
    (codePoint) => unicodeV11.wcwidthLegacy(codePoint) == 0,
  );
  writeRanges(
    result,
    'LEGACY_WIDE',
    (codePoint) => unicodeV11.wcwidthLegacy(codePoint) == 2,
  );
  writeRanges(result, 'AMBIGUOUS', isAmbiguousWidth);
  writeRanges(result, 'EXTENDED_PICTOGRAPHIC', isExtendedPictographic);

  final generated = '${result.toString().trimRight()}\n';
  if (arguments.contains('--check')) {
    if (!output.existsSync() || output.readAsStringSync() != generated) {
      stderr.writeln(
        'Terminal width table is stale. Run dart tool/generate_terminal_width_table.dart',
      );
      exitCode = 1;
    }
  } else {
    output.writeAsStringSync(generated);
  }
}

void writeRanges(
  StringBuffer output,
  String name,
  bool Function(int) contains,
) {
  output.writeln('pub(super) const $name: &[(u32, u32)] = &[');
  int? start;
  for (var codePoint = 0; codePoint <= 0x110000; codePoint++) {
    final included =
        codePoint < 0x110000 &&
        (codePoint < 0xd800 || codePoint > 0xdfff) &&
        contains(codePoint);
    if (included && start == null) start = codePoint;
    if (!included && start != null) {
      output.writeln(
        '    (0x${start.toRadixString(16)}, 0x${(codePoint - 1).toRadixString(16)}),',
      );
      start = null;
    }
  }
  output.writeln('];');
  output.writeln();
}
